"""FIFO queue for notifications generated by triggered alerts."""

from collections import deque
from dataclasses import dataclass
from typing import Protocol

from models.alert import Alert, AlertStatus


@dataclass(frozen=True)
class Notification:
    """Alert details to deliver, including the price that triggered it."""

    alert: Alert
    current_price: float
    recovered: bool = False

    @property
    def message(self) -> str:
        """Return a concise description suitable for notification channels."""
        alert = self.alert
        message = (
            f"{alert.alert_id}: {alert.symbol} {alert.condition.value} "
            f"{alert.target_price:.2f} (current: {self.current_price:.2f})"
        )
        return f"RECOVERED ALERT: {message}" if self.recovered else message


class NotificationProcessor(Protocol):
    """Interface for a component that delivers one notification."""

    def handle(self, notification: Notification) -> None:
        """Deliver a notification."""


class NotificationQueue:
    """Store triggered-alert notifications in insertion order."""

    def __init__(self) -> None:
        self._items: deque[Notification] = deque()

    def enqueue(
        self,
        alert: Alert,
        current_price: float,
        *,
        recovered: bool = False,
    ) -> None:
        """Add a triggered alert to the end of the queue."""
        if alert.status is not AlertStatus.TRIGGERED:
            raise ValueError("only triggered alerts can be enqueued")
        self._items.append(Notification(alert, current_price, recovered))

    def dequeue(self) -> Notification:
        """Remove and return the oldest notification."""
        return self._items.popleft()

    def is_empty(self) -> bool:
        """Return whether the queue has no pending notifications."""
        return not self._items

    def size(self) -> int:
        """Return the number of pending notifications."""
        return len(self._items)

    def process_next(
        self, handler: NotificationProcessor
    ) -> Notification | None:
        """Deliver the oldest queued notification, if one is available."""
        if self.is_empty():
            return None
        notification = self.dequeue()
        handler.handle(notification)
        return notification

    def process_all(self, handler: NotificationProcessor) -> list[Notification]:
        """Deliver all pending notifications in FIFO order."""
        processed: list[Notification] = []
        while not self.is_empty():
            notification = self.process_next(handler)
            if notification is not None:
                processed.append(notification)
        return processed
